INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 25, 'theory', 'Quiz: higher-order functions');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 25, 0, 'What is passed in sorted(words, key=len)?', '["The result of len(words)", "The function len itself, uncalled", "The length of the first word", "A number"]', 1, 'The function is passed without parentheses: sorted will call it on each element itself.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 25, 1, 'What is (lambda a, b: a + b)(2, 3) equal to?', '["5", "23", "An error: lambda has no return", "None"]', 0, 'The body of a lambda is an expression, and its value is the result; no return is needed.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 25, 2, 'm = map(str, [1, 2]); list(m); list(m). What does the second list return?', '["[''1'', ''2'']", "[]", "An error", "None"]', 1, 'map returns a single-use iterator: after the first pass it is exhausted.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 25, 3, 'What does list(filter(None, [0, 1, '''', ''a'', []])) do?', '["Keeps only the empty values", "Removes the falsy values, leaving [1, ''a'']", "Raises an error", "Returns an empty list"]', 1, 'With None as the function, filter selects the elements that are true by themselves.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 25, 4, 'Why do all the lambdas in funcs = [lambda: i for i in range(3)] return 2?', '["An interpreter bug", "A lambda remembers the variable i itself, not its value at creation time", "range returned a single digit", "Lambdas cannot be stored in a list"]', 1, 'Late binding: the value of i is read at call time, when the loop has already finished.');
